def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    strong_bids = []
    weak_bids = []

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) >= 100:
                    strong_bids.append(float(bid))
                else:
                    weak_bids.append(float(bid))

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 18.0))

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))

    urgent = hp <= 3 or no_water_days >= 2
    semi_urgent = hp <= 5 or no_water_days >= 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    weak_anchor = max(weak_bids) if weak_bids else 55.0
    strong_count = len(strong_bids)

    if urgent:
        bid = 110.0 + 25.0 * scarcity
        if highest_prev > bid:
            bid = highest_prev + 3.0
    elif supply >= 22:
        bid = 42.0
        if weak_bids:
            bid = min(65.0, weak_anchor + 2.0)
    elif supply >= 19:
        bid = 58.0 + 8.0 * scarcity
        if weak_bids:
            bid = max(bid, weak_anchor + 2.5)
        if strong_count >= 2 and semi_urgent:
            bid = max(bid, 95.0)
    else:
        bid = 68.0 + 14.0 * scarcity
        if weak_bids:
            bid = max(bid, weak_anchor + 3.0)
        if strong_count >= 2:
            bid = max(bid, 88.0 if not semi_urgent else 108.0)

    if day >= 8:
        bid += 6.0
    if hp >= 8 and supply >= 22 and strong_count >= 2:
        bid -= 8.0
    if budget < 120:
        bid = min(bid, 0.55 * budget)
    elif budget < 200:
        bid = min(bid, 0.7 * budget)

    bid = max(0.0, min(float(budget), bid))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    # If we are in critical health, bid aggressively to prevent further no-water days.
    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    # Collect yesterday bids from alive opponents only.
    alive_opps = []
    for opp in opponents_status.values():
        if opp.get('alive', False):
            alive_opps.append(opp)

    # Compute a pressure estimate from yesterday.
    yesterday_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        if prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass

    # Baseline bid depends on expected number of water units.
    # If supply is tight (15), only 1 unit of 9 fits; if supply is 18-25, 2 units may fit.
    # We don't know allocation mechanics, so we use this to scale our aggressiveness.
    if supply < (WATER_REQ + 1):
        supply_tight = True
    else:
        supply_tight = False

    # Determine target bid using yesterday's distribution.
    # Cindy-like behavior suggests some agents overpay; we aim around the lower-mid to avoid waste.
    if yesterday_bids:
        sorted_bids = sorted(yesterday_bids)
        n = len(sorted_bids)
        median_bid = sorted_bids[int(n // 2)]
        # Also consider high-pressure tail.
        high_bid = sorted_bids[-1]

        # If someone bid very high yesterday, others likely followed; raise our bid slightly.
        if high_bid >= DAILY_SALARY * 1.5:
            target = median_bid + 5.0
        else:
            target = median_bid * 0.85 + 10.0
    else:
        target = DAILY_SALARY * 0.55

    # Health/no-water urgency adjustment.
    if hp <= 2 or no_water_days >= 2:
        target *= 1.35
    elif hp <= 4:
        target *= 1.15

    # Tight supply adjustment: bid more when supply likely limits water.
    if supply_tight:
        target *= 1.10
    else:
        target *= 0.95

    # Clamp to budget and keep within a reasonable fraction of daily salary.
    # Avoid extreme bids that could mirror Cindy's wasteful pattern.
    max_reasonable = DAILY_SALARY * 1.2
    bid = min(budget, max_reasonable, target)

    # If budget is too low, still bid something if possible.
    if bid <= 0.0:
        return 0.0
    return float(bid)

